functions.adjust_inventory_usage_actual_atomic:
CREATE OR REPLACE FUNCTION public.adjust_inventory_usage_actual_atomic(p_transaction_id bigint, p_actual_qty numeric, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  actor_role text;
  actor_name text;
  original public.inventory_transactions%ROWTYPE;
  correction numeric;
  new_unit_stock numeric;
  adjustment_id bigint;
BEGIN
  actor_role := CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role IS NULL OR actor_role NOT IN ('Owner','Admin','service_role') THEN RAISE EXCEPTION 'Akses ditolak' USING ERRCODE='42501'; END IF;
  IF p_actual_qty IS NULL OR p_actual_qty < 0 THEN RAISE EXCEPTION 'Qty aktual tidak valid'; END IF;
  SELECT name INTO actor_name FROM public.user_profiles WHERE id=auth.uid(); actor_name:=coalesce(actor_name,nullif(trim(p_actor_name),''),actor_role);

  SELECT * INTO original FROM public.inventory_transactions WHERE id=p_transaction_id FOR UPDATE;
  IF NOT FOUND OR original.type <> 'usage' OR original.qty >= 0 THEN RAISE EXCEPTION 'Transaksi pemakaian tidak ditemukan'; END IF;
  IF original.qty_actual IS NOT NULL THEN RAISE EXCEPTION 'Qty aktual transaksi ini sudah pernah dikonfirmasi'; END IF;
  -- Ledger awal = -estimasi. Agar net menjadi -aktual, koreksi = estimasi - aktual.
  correction := round(abs(original.qty) - p_actual_qty, 3);

  UPDATE public.inventory_transactions SET qty_actual=-p_actual_qty WHERE id=original.id;
  IF abs(correction) >= 0.001 THEN
    INSERT INTO public.inventory_transactions
      (inventory_code,inventory_name,order_id,report_id,qty,qty_actual,type,unit_id,unit_label,
       notes,customer_name,teknisi_name,job_date,created_by,created_by_name,source_transaction_id)
    VALUES
      (original.inventory_code,original.inventory_name,original.order_id,original.report_id,
       correction,correction,'adjustment',original.unit_id,original.unit_label,
       'Koreksi timbang aktual dari '||abs(original.qty)||' → '||p_actual_qty||' (transaksi '||original.id||')',
       original.customer_name,original.teknisi_name,original.job_date,auth.uid(),actor_name,original.id)
    RETURNING id INTO adjustment_id;
    IF original.unit_id IS NOT NULL THEN
      UPDATE public.inventory_units SET stock=stock+correction,updated_at=now()
       WHERE id=original.unit_id AND stock+correction>=0 RETURNING stock INTO new_unit_stock;
      IF new_unit_stock IS NULL THEN RAISE EXCEPTION 'Stok unit tidak cukup untuk koreksi timbang'; END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('transaction_id',original.id,'qty_actual',-p_actual_qty,
    'correction',correction,'adjustment_id',adjustment_id,'unit_id',original.unit_id,'unit_stock',new_unit_stock);
END $function$

functions.confirm_material_checkout_atomic:
CREATE OR REPLACE FUNCTION public.confirm_material_checkout_atomic(p_session_id uuid, p_movements jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_session_items jsonb DEFAULT NULL::jsonb, p_admin_adjustments jsonb DEFAULT '[]'::jsonb, p_confirm_notes text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  actor_role text;
  actor_name text;
  sess public.teknisi_material_checkout%ROWTYPE;
  movement jsonb;
  tx_id bigint;
  tx_ids jsonb := '[]'::jsonb;
  qty_value numeric;
  unit_uuid uuid;
  unit_row public.inventory_units%ROWTYPE;
  inventory_name_value text;
BEGIN
  actor_role := CASE WHEN auth.role() = 'service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role IS NULL OR actor_role NOT IN ('Owner','Admin','service_role') THEN
    RAISE EXCEPTION 'Hanya Owner/Admin yang dapat mengonfirmasi material' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(coalesce(p_movements, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Daftar mutasi material tidak valid';
  END IF;
  SELECT name INTO actor_name FROM public.user_profiles WHERE id = auth.uid();
  actor_name := coalesce(actor_name, nullif(trim(p_actor_name), ''), actor_role);

  SELECT * INTO sess FROM public.teknisi_material_checkout
   WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sesi material tidak ditemukan'; END IF;
  IF sess.session_type NOT IN ('pulang','pakai') THEN RAISE EXCEPTION 'Jenis sesi tidak dapat dikonfirmasi'; END IF;
  IF sess.confirm_status <> 'PENDING' THEN RAISE EXCEPTION 'Sesi sudah diproses oleh pengguna lain'; END IF;
  IF p_expected_updated_at IS NOT NULL AND sess.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Sesi berubah sejak dibuka; muat ulang sebelum konfirmasi';
  END IF;
  IF jsonb_array_length(coalesce(sess.deduct_tx_ids, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'Sesi sudah memiliki transaksi pemotongan';
  END IF;

  FOR movement IN SELECT value FROM jsonb_array_elements(coalesce(p_movements, '[]'::jsonb)) LOOP
    unit_row := NULL;
    BEGIN
      qty_value := round((movement->>'qty')::numeric, 3);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Qty mutasi material tidak valid';
    END;
    IF qty_value <= 0 THEN RAISE EXCEPTION 'Qty mutasi material harus lebih dari 0'; END IF;
    IF nullif(trim(movement->>'inventory_code'), '') IS NULL THEN
      RAISE EXCEPTION 'Kode inventori wajib diisi pada setiap mutasi';
    END IF;

    unit_uuid := nullif(movement->>'unit_id', '')::uuid;
    IF unit_uuid IS NOT NULL THEN
      SELECT * INTO unit_row FROM public.inventory_units WHERE id = unit_uuid FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Unit stok % tidak ditemukan', unit_uuid; END IF;
      IF unit_row.archived OR unit_row.is_active = false THEN
        RAISE EXCEPTION 'Unit % sudah nonaktif/diarsipkan', unit_row.unit_label;
      END IF;
      IF unit_row.inventory_code IS DISTINCT FROM movement->>'inventory_code' THEN
        RAISE EXCEPTION 'Unit % tidak cocok dengan kode inventori', unit_row.unit_label;
      END IF;
      IF unit_row.stock < qty_value THEN
        RAISE EXCEPTION 'Stok % tidak cukup: tersedia %, diminta %', unit_row.unit_label, unit_row.stock, qty_value;
      END IF;
    END IF;

    SELECT name INTO inventory_name_value FROM public.inventory WHERE code = movement->>'inventory_code' FOR UPDATE;
    IF inventory_name_value IS NULL THEN RAISE EXCEPTION 'Item inventori % tidak ditemukan', movement->>'inventory_code'; END IF;

    INSERT INTO public.inventory_transactions
      (inventory_code, inventory_name, qty, qty_actual, type, teknisi_name,
       job_date, order_id, unit_id, unit_label, notes, customer_name,
       created_by, created_by_name)
    VALUES
      (movement->>'inventory_code', coalesce(nullif(movement->>'inventory_name',''), inventory_name_value),
       -qty_value, -qty_value, 'usage', sess.teknisi_name,
       coalesce(nullif(movement->>'job_date','')::date, sess.checkout_date),
       nullif(movement->>'order_id',''), unit_uuid,
       coalesce(nullif(movement->>'unit_label',''), unit_row.unit_label),
       coalesce(nullif(movement->>'notes',''), 'Material Harian confirm oleh ' || actor_name),
       nullif(movement->>'customer_name',''), auth.uid(), actor_name)
    RETURNING id INTO tx_id;
    tx_ids := tx_ids || jsonb_build_array(tx_id);

    IF unit_uuid IS NOT NULL THEN
      UPDATE public.inventory_units
         SET stock = stock - qty_value, updated_at = now()
       WHERE id = unit_uuid;
    END IF;
  END LOOP;

  UPDATE public.teknisi_material_checkout
     SET confirm_status = 'CONFIRMED', confirmed_by = actor_name, confirmed_at = now(),
         deduct_tx_ids = tx_ids,
         items = coalesce(p_session_items, sess.items),
         admin_adjustments = coalesce(p_admin_adjustments, '[]'::jsonb),
         confirm_notes = nullif(trim(p_confirm_notes), ''), updated_at = now()
   WHERE id = sess.id;

  RETURN jsonb_build_object('session_id', sess.id, 'deduct_tx_ids', tx_ids,
    'movement_count', jsonb_array_length(coalesce(p_movements, '[]'::jsonb)));
END $function$

functions.create_order_workflow_atomic:
CREATE OR REPLACE FUNCTION public.create_order_workflow_atomic(p_order jsonb, p_auto_dispatch boolean DEFAULT false, p_actor_name text DEFAULT NULL::text, p_mutation_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  role_name text; actor text; ord public.orders%ROWTYPE; customer_row public.customers%ROWTYPE;
  result_value jsonb; claimed integer; mkey text; slot_ok boolean; normalized_phone text;
  oid text:=nullif(p_order->>'id','');
BEGIN
  role_name:=CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF role_name IS NULL OR role_name NOT IN ('Owner','Admin','Finance','service_role') THEN RAISE EXCEPTION 'Akses membuat order ditolak' USING ERRCODE='42501'; END IF;
  IF jsonb_typeof(p_order) IS DISTINCT FROM 'object' OR oid IS NULL THEN RAISE EXCEPTION 'Payload order tidak lengkap'; END IF;
  SELECT name INTO actor FROM public.user_profiles WHERE id=auth.uid(); actor:=coalesce(actor,nullif(trim(p_actor_name),''),role_name);
  mkey:=coalesce(nullif(trim(p_mutation_key),''),'order-create:'||oid);
  INSERT INTO public.operational_mutations(mutation_key,operation,actor_id,actor_name)
  VALUES(mkey,'CREATE_ORDER',auth.uid(),actor) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS claimed=ROW_COUNT;
  IF claimed=0 THEN SELECT om.result INTO result_value FROM public.operational_mutations om WHERE om.mutation_key=mkey; RETURN result_value||jsonb_build_object('replayed',true); END IF;

  normalized_phone:=regexp_replace(coalesce(p_order->>'phone',''),'[^0-9]','','g');
  IF normalized_phone LIKE '0%' THEN normalized_phone:='62'||substr(normalized_phone,2); END IF;
  IF nullif(p_order->>'customer_id','') IS NOT NULL THEN
    SELECT * INTO customer_row FROM public.customers WHERE id=p_order->>'customer_id' FOR UPDATE;
  END IF;
  IF customer_row.id IS NULL AND normalized_phone<>'' THEN
    SELECT * INTO customer_row FROM public.customers
    WHERE phone=normalized_phone AND lower(trim(name))=lower(trim(p_order->>'customer')) LIMIT 1 FOR UPDATE;
  END IF;
  IF customer_row.id IS NULL AND normalized_phone<>'' THEN
    INSERT INTO public.customers(name,phone,address,area,notes,is_vip,total_orders,joined_date,last_service)
    VALUES(trim(p_order->>'customer'),normalized_phone,coalesce(p_order->>'address',''),coalesce(p_order->>'area',''),'',false,0,
      (p_order->>'date')::date,(p_order->>'date')::date)
    RETURNING * INTO customer_row;
  END IF;

  INSERT INTO public.orders(
    id,customer,customer_id,phone,address,area,service,type,units,teknisi,helper,teknisi2,helper2,teknisi3,helper3,
    date,time,time_end,status,team_slot,invoice_id,dispatch,dispatch_at,notes,parent_job_id,is_multi_day,
    maintenance_client_id,maintenance_unit_ids,source,last_changed_by
  ) VALUES(
    oid,p_order->>'customer',customer_row.id,normalized_phone,p_order->>'address',p_order->>'area',p_order->>'service',p_order->>'type',
    greatest(coalesce((p_order->>'units')::integer,1),1),p_order->>'teknisi',nullif(p_order->>'helper',''),
    nullif(p_order->>'teknisi2',''),nullif(p_order->>'helper2',''),nullif(p_order->>'teknisi3',''),nullif(p_order->>'helper3',''),
    (p_order->>'date')::date,nullif(p_order->>'time','')::time,nullif(p_order->>'time_end','')::time,
    CASE WHEN p_auto_dispatch THEN 'DISPATCHED' ELSE 'CONFIRMED' END,
    nullif(p_order->>'team_slot',''),NULL,p_auto_dispatch,CASE WHEN p_auto_dispatch THEN now() ELSE NULL END,
    coalesce(p_order->>'notes',''),nullif(p_order->>'parent_job_id',''),coalesce((p_order->>'is_multi_day')::boolean,false),
    nullif(p_order->>'maintenance_client_id','')::uuid,coalesce(p_order->'maintenance_unit_ids','[]'::jsonb),
    coalesce(nullif(p_order->>'source',''),'manual'),actor
  ) RETURNING * INTO ord;

  IF nullif(ord.teknisi,'') IS NOT NULL AND ord.date IS NOT NULL AND ord.time IS NOT NULL AND ord.time_end IS NOT NULL THEN
    SELECT public.try_claim_teknisi_slot(ord.teknisi,ord.date,ord.id,ord.time,ord.time_end) INTO slot_ok;
    IF slot_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Slot teknisi baru saja terisi'; END IF;
  END IF;
  IF customer_row.id IS NOT NULL THEN
    UPDATE public.customers SET total_orders=coalesce(total_orders,0)+1,last_service=ord.date WHERE id=customer_row.id RETURNING * INTO customer_row;
  END IF;
  result_value:=jsonb_build_object('order',to_jsonb(ord),'customer',CASE WHEN customer_row.id IS NULL THEN NULL ELSE to_jsonb(customer_row) END,'replayed',false);
  UPDATE public.operational_mutations SET result=result_value,completed_at=now() WHERE mutation_key=mkey;
  RETURN result_value;
END $function$

functions.finalize_service_report_atomic:
CREATE OR REPLACE FUNCTION public.finalize_service_report_atomic(p_report_id text, p_invoice jsonb DEFAULT NULL::jsonb, p_actor_name text DEFAULT NULL::text, p_mutation_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  role_name text; actor text; r public.service_reports%ROWTYPE; o public.orders%ROWTYPE;
  inv public.invoices%ROWTYPE; initial_job text; initial_group text; is_group boolean;
  work_ids text[]; locked_work_ids text[]; lock_ids text[]; candidate_ids text[]; n_candidates integer;
  team_count integer; verified_count integer; group_value jsonb := NULL;
  order_values jsonb := '[]'::jsonb; result_value jsonb; mkey text; receipt public.operational_mutations%ROWTYPE;
BEGIN
  role_name := CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF role_name IS NULL OR role_name NOT IN ('Owner','Admin','service_role') THEN
    RAISE EXCEPTION 'Hanya Owner/Admin dapat memfinalisasi laporan' USING ERRCODE='42501';
  END IF;
  IF nullif(trim(p_report_id),'') IS NULL THEN RAISE EXCEPTION 'Report ID wajib diisi'; END IF;
  SELECT * INTO r FROM public.service_reports WHERE id=p_report_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Laporan tidak ditemukan'; END IF;
  initial_job := r.job_id;
  SELECT * INTO o FROM public.orders WHERE id=initial_job;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order laporan tidak ditemukan'; END IF;
  is_group := coalesce(o.is_team_split,false) AND nullif(o.job_group_id,'') IS NOT NULL;
  initial_group := CASE WHEN is_group THEN o.job_group_id ELSE o.id END;
  IF is_group THEN
    SELECT array_agg(id ORDER BY id) INTO work_ids FROM public.orders
      WHERE job_group_id=initial_group AND coalesce(is_team_split,false);
  ELSE work_ids := ARRAY[o.id]; END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO lock_ids FROM unnest(work_ids||ARRAY[initial_group]) x;
  -- Both wrappers take order locks before report/log locks; stale browsers cannot bypass this.
  PERFORM t.id FROM public.orders t WHERE t.id=ANY(lock_ids) ORDER BY t.id FOR UPDATE;
  IF is_group THEN
    SELECT array_agg(id ORDER BY id) INTO locked_work_ids FROM public.orders
      WHERE job_group_id=initial_group AND coalesce(is_team_split,false);
    IF locked_work_ids IS DISTINCT FROM work_ids THEN RAISE EXCEPTION 'Anggota grup berubah; muat ulang sebelum verifikasi'; END IF;
  END IF;
  SELECT * INTO r FROM public.service_reports WHERE id=p_report_id FOR UPDATE;
  SELECT * INTO o FROM public.orders WHERE id=initial_job;
  IF r.job_id IS DISTINCT FROM initial_job OR
    (CASE WHEN coalesce(o.is_team_split,false) AND nullif(o.job_group_id,'') IS NOT NULL THEN o.job_group_id ELSE o.id END) IS DISTINCT FROM initial_group THEN
    RAISE EXCEPTION 'Tautan laporan/grup berubah; muat ulang sebelum verifikasi';
  END IF;
  IF r.status NOT IN ('SUBMITTED','REVISION','VERIFIED') OR r.status IS NULL THEN
    RAISE EXCEPTION 'Status laporan tidak dapat diverifikasi';
  END IF;
  IF EXISTS(SELECT 1 FROM public.orders WHERE id=ANY(work_ids) AND upper(status) IN ('CANCELLED','RESCHEDULED')) THEN
    RAISE EXCEPTION 'Order dibatalkan atau dijadwal ulang; verifikasi ditahan';
  END IF;
  PERFORM l.id FROM public.maintenance_logs l WHERE l.order_id=ANY(work_ids) ORDER BY l.id FOR UPDATE;
  SELECT array_agg(DISTINCT i.id ORDER BY i.id) INTO candidate_ids FROM public.invoices i
    WHERE i.status IS DISTINCT FROM 'CANCELLED' AND (
      i.job_id=ANY(work_ids) OR (is_group AND i.job_id=initial_group)
      OR i.id IN (SELECT t.invoice_id FROM public.orders t WHERE t.id=ANY(lock_ids))
      OR i.id IN (SELECT l.invoice_id FROM public.maintenance_logs l WHERE l.order_id=ANY(work_ids))
    );
  n_candidates := coalesce(cardinality(candidate_ids),0);
  IF n_candidates>1 THEN
    RAISE EXCEPTION 'Ada beberapa invoice aktif untuk pekerjaan/grup ini; periksa tautan invoice dahulu. Tidak membuat invoice baru';
  END IF;
  IF n_candidates=0 THEN
    IF EXISTS(SELECT 1 FROM public.maintenance_logs l WHERE l.order_id=ANY(work_ids) AND
      (l.invoiced IS TRUE OR l.invoice_id IS NOT NULL)) THEN
      RAISE EXCEPTION 'Log sudah ditagih tetapi tautan invoice tidak jelas/aktif; periksa Maintenance sebelum verifikasi';
    END IF;
    -- New work uses the original atomic workflow, including all team completeness rules.
    RETURN public.finalize_service_report_atomic_base_209(p_report_id,p_invoice,p_actor_name,p_mutation_key);
  END IF;

  SELECT * INTO inv FROM public.invoices WHERE id=candidate_ids[1] FOR UPDATE;
  IF inv.status IS NULL OR inv.status NOT IN ('PENDING_APPROVAL','APPROVED','UNPAID','OVERDUE','PARTIAL_PAID','PAID') THEN
    RAISE EXCEPTION 'Status invoice tertaut perlu diperiksa; verifikasi ditahan';
  END IF;
  IF EXISTS(SELECT 1 FROM public.orders t WHERE t.id=ANY(work_ids) AND
    t.maintenance_client_id IS NOT NULL AND inv.maintenance_client_id IS NOT NULL AND t.maintenance_client_id<>inv.maintenance_client_id) THEN
    RAISE EXCEPTION 'Invoice tertaut bukan milik perusahaan maintenance pekerjaan ini';
  END IF;
  IF is_group AND inv.job_id IS DISTINCT FROM initial_group AND EXISTS(
    SELECT 1 FROM public.orders t WHERE t.id=ANY(work_ids) AND t.invoice_id IS DISTINCT FROM inv.id
  ) THEN
    RAISE EXCEPTION 'Invoice hanya mencakup sebagian tim; periksa tautan grup sebelum verifikasi';
  END IF;
  SELECT name INTO actor FROM public.user_profiles WHERE id=auth.uid();
  actor := coalesce(actor,nullif(trim(p_actor_name),''),role_name);
  mkey := coalesce(nullif(trim(p_mutation_key),''),'report-finalize:'||p_report_id);
  SELECT * INTO receipt FROM public.operational_mutations WHERE mutation_key=mkey FOR UPDATE;
  IF FOUND AND (receipt.operation IS DISTINCT FROM 'FINALIZE_REPORT'
    OR (receipt.result->'report'->>'id' IS NOT NULL AND receipt.result->'report'->>'id'<>p_report_id)) THEN
    RAISE EXCEPTION 'ID permintaan telah digunakan proses lain';
  END IF;
  -- Reusing a linked invoice NEVER overwrites totals, items, cash, paid status or PDF.
  UPDATE public.service_reports SET status='VERIFIED',last_changed_by=actor,updated_at=now()
    WHERE id=r.id RETURNING * INTO r;
  IF is_group THEN
    team_count := cardinality(work_ids);
    SELECT count(DISTINCT job_id) INTO verified_count FROM public.service_reports
      WHERE job_id=ANY(work_ids) AND status='VERIFIED';
    group_value := jsonb_build_object('id',initial_group,'team_count',team_count,'verified_count',verified_count,'ready',verified_count=team_count);
  END IF;
  UPDATE public.orders SET status=CASE WHEN inv.status='PAID' THEN 'PAID' ELSE 'COMPLETED' END,
    invoice_id=inv.id,last_changed_by=actor
    WHERE id=o.id OR (is_group AND verified_count=team_count AND id=ANY(work_ids));
  SELECT * INTO o FROM public.orders WHERE id=initial_job;
  IF is_group THEN SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) INTO order_values
    FROM public.orders t WHERE t.id=ANY(work_ids); END IF;
  result_value := jsonb_build_object('report',to_jsonb(r),'order',to_jsonb(o),'orders',order_values,
    'invoice',to_jsonb(inv),'group',group_value,'invoice_reused',true,
    'replayed',receipt.completed_at IS NOT NULL);
  INSERT INTO public.operational_mutations(mutation_key,operation,actor_id,actor_name,result,completed_at)
    VALUES(mkey,'FINALIZE_REPORT',auth.uid(),actor,result_value,now())
    ON CONFLICT(mutation_key) DO UPDATE SET result=excluded.result,completed_at=excluded.completed_at;
  RETURN result_value;
END $function$

functions.guard_combined_transfer_229:
CREATE OR REPLACE FUNCTION public.guard_combined_transfer_229()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_TABLE_NAME='invoice_payments' THEN
    IF TG_OP IN ('UPDATE','DELETE') AND OLD.combined_transfer_detail IS NOT NULL THEN
      RAISE EXCEPTION 'Alokasi transfer gabungan tidak boleh diubah/dihapus lewat jalur biasa';
    END IF;
    -- Custom GUCs can be set by clients. They are never sufficient on their own:
    -- allow only the security-definer owner to add audit metadata, without
    -- changing any existing financial field in the same UPDATE.
    IF TG_OP='UPDATE' AND NEW.combined_transfer_detail IS NOT NULL
      AND current_setting('app.combined_transfer_write',true)='allowed'
      AND current_user=(SELECT pg_get_userbyid(proowner) FROM pg_proc
        WHERE oid='public.confirm_invoice_wa_combined_transfer_atomic(uuid,text,uuid,text,jsonb,date,text,boolean)'::regprocedure)
      AND (to_jsonb(NEW)-ARRAY['combined_transfer_detail','updated_at']) IS NOT DISTINCT FROM
          (to_jsonb(OLD)-ARRAY['combined_transfer_detail','updated_at']) THEN
      RETURN NEW;
    END IF;
    IF TG_OP IN ('INSERT','UPDATE') AND NEW.combined_transfer_detail IS NOT NULL THEN
      RAISE EXCEPTION 'Alokasi transfer gabungan hanya boleh dicatat lewat verifikasi atomik';
    END IF;
  ELSE
    IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM public.invoice_payments ip WHERE ip.invoice_id=OLD.id AND ip.combined_transfer_detail IS NOT NULL) THEN
      RAISE EXCEPTION 'Invoice dengan alokasi transfer gabungan tidak boleh dihapus';
    END IF;
    IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.invoice_payments ip WHERE ip.invoice_id=OLD.id AND ip.combined_transfer_detail IS NOT NULL)
      AND (to_jsonb(NEW)-ARRAY['updated_at','pdf_url','pdf_generated_at','last_changed_by','sent','sent_at','wa_sent_count','wa_last_sent_at','wa_last_sent_by','wa_last_sent_mode','wa_last_sent_method']) IS DISTINCT FROM
          (to_jsonb(OLD)-ARRAY['updated_at','pdf_url','pdf_generated_at','last_changed_by','sent','sent_at','wa_sent_count','wa_last_sent_at','wa_last_sent_by','wa_last_sent_mode','wa_last_sent_method']) THEN
      RAISE EXCEPTION 'Invoice dengan alokasi transfer gabungan dikunci untuk perubahan/revert biasa';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

functions.guard_invoice_total_against_payments:
CREATE OR REPLACE FUNCTION public.guard_invoice_total_against_payments()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE ledger_total numeric;
BEGIN
  SELECT coalesce(sum(amount),0) INTO ledger_total
    FROM public.invoice_payments WHERE invoice_id=OLD.id;
  ledger_total:=greatest(ledger_total,coalesce(OLD.paid_amount,0));
  IF coalesce(NEW.total,0)<ledger_total THEN
    RAISE EXCEPTION 'Total invoice tidak boleh lebih kecil dari pembayaran yang sudah diterima (%)',ledger_total;
  END IF;
  RETURN NEW;
END $function$

functions.guard_reviewed_withholding_212:
CREATE OR REPLACE FUNCTION public.guard_reviewed_withholding_212()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF current_setting('app.reviewed_withholding_write',true)='allowed' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME='invoice_payments' THEN
    IF TG_OP IN ('DELETE','UPDATE') THEN
      IF OLD.withheld_amount>0 THEN RAISE EXCEPTION 'Pembayaran dengan potongan PPh tidak boleh diubah/dihapus lewat jalur biasa; perlukan pembalikan terverifikasi'; END IF;
    END IF;
    IF TG_OP IN ('INSERT','UPDATE') THEN
      IF NEW.withheld_amount>0 OR NEW.withholding_detail IS NOT NULL THEN RAISE EXCEPTION 'Potongan PPh hanya boleh dicatat melalui verifikasi atomik'; END IF;
    END IF;
  ELSE
    IF TG_OP='DELETE' AND OLD.withheld_amount>0 THEN RAISE EXCEPTION 'Invoice dengan potongan PPh tidak boleh dihapus'; END IF;
    IF TG_OP='INSERT' AND NEW.withheld_amount>0 THEN RAISE EXCEPTION 'Potongan PPh hanya boleh dicatat melalui verifikasi atomik'; END IF;
    IF TG_OP='UPDATE' THEN
      IF NEW.withheld_amount IS DISTINCT FROM OLD.withheld_amount OR (OLD.withheld_amount>0 AND
        (to_jsonb(NEW)-ARRAY['updated_at','pdf_url','pdf_generated_at','last_changed_by','sent','sent_at','wa_sent_count','wa_last_sent_at','wa_last_sent_by','wa_last_sent_mode','wa_last_sent_method','wa_last_sent_batch']) IS DISTINCT FROM
        (to_jsonb(OLD)-ARRAY['updated_at','pdf_url','pdf_generated_at','last_changed_by','sent','sent_at','wa_sent_count','wa_last_sent_at','wa_last_sent_by','wa_last_sent_mode','wa_last_sent_method','wa_last_sent_batch'])) THEN
        RAISE EXCEPTION 'Invoice dengan potongan PPh dikunci untuk perubahan/revert biasa; perlukan pembalikan terverifikasi';
      END IF;
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

functions.record_invoice_partial_payment_atomic:
CREATE OR REPLACE FUNCTION public.record_invoice_partial_payment_atomic(p_payment_id uuid, p_invoice_id text, p_amount numeric, p_method text, p_notes text, p_paid_at date, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  actor_role text;
  actor_name text;
  inv public.invoices%ROWTYPE;
  previous public.invoice_payments%ROWTYPE;
  already_paid numeric;
  remaining numeric;
BEGIN
  actor_role := CASE WHEN auth.role() = 'service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role NOT IN ('Owner','Admin','Finance','service_role') THEN
    RAISE EXCEPTION 'Akses pembayaran ditolak' USING ERRCODE = '42501';
  END IF;
  IF p_payment_id IS NULL OR nullif(trim(p_invoice_id),'') IS NULL
     OR p_amount IS NULL OR p_amount <= 0 OR p_paid_at IS NULL
     OR nullif(trim(p_method),'') IS NULL THEN
    RAISE EXCEPTION 'Data pembayaran tidak lengkap';
  END IF;

  -- Kunci invoice menserialkan dua admin/tab yang mencatat pembayaran bersamaan.
  SELECT * INTO inv FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice tidak ditemukan'; END IF;
  SELECT * INTO previous FROM public.invoice_payments WHERE id = p_payment_id;
  IF FOUND THEN
    IF previous.invoice_id IS DISTINCT FROM p_invoice_id
       OR previous.amount IS DISTINCT FROM p_amount
       OR previous.method IS DISTINCT FROM p_method
       OR previous.paid_at IS DISTINCT FROM p_paid_at
       OR previous.notes IS DISTINCT FROM nullif(trim(p_notes),'') THEN
      RAISE EXCEPTION 'ID pembayaran sudah dipakai untuk data berbeda';
    END IF;
    RETURN jsonb_build_object('invoice',to_jsonb(inv),'payment',to_jsonb(previous),'replayed',true);
  END IF;

  IF inv.status IN ('PAID','CANCELLED') THEN RAISE EXCEPTION 'Invoice sudah lunas/dibatalkan'; END IF;
  already_paid := greatest(0, coalesce(inv.paid_amount, 0));
  remaining := greatest(0, coalesce(inv.total, 0) - already_paid);
  IF p_amount > remaining THEN RAISE EXCEPTION 'Nominal melebihi sisa tagihan (%)', remaining; END IF;

  SELECT name INTO actor_name FROM public.user_profiles WHERE id = auth.uid();
  actor_name := coalesce(actor_name, nullif(trim(p_actor_name),''), actor_role);
  INSERT INTO public.invoice_payments
    (id,invoice_id,amount,method,notes,paid_at,recorded_by_name)
  VALUES
    (p_payment_id,p_invoice_id,p_amount,p_method,nullif(trim(p_notes),''),p_paid_at,actor_name)
  RETURNING * INTO previous;

  UPDATE public.invoices
     SET paid_amount = already_paid + p_amount,
         remaining_amount = remaining - p_amount,
         status = CASE WHEN remaining = p_amount THEN 'PAID' ELSE 'PARTIAL_PAID' END,
         paid_at = CASE WHEN remaining = p_amount THEN p_paid_at ELSE paid_at END
   WHERE id = p_invoice_id RETURNING * INTO inv;

  RETURN jsonb_build_object('invoice',to_jsonb(inv),'payment',to_jsonb(previous),'replayed',false);
END $function$

functions.reopen_material_checkout_atomic:
CREATE OR REPLACE FUNCTION public.reopen_material_checkout_atomic(p_session_id uuid, p_reason text, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  actor_role text;
  actor_name text;
  sess public.teknisi_material_checkout%ROWTYPE;
  old_tx public.inventory_transactions%ROWTYPE;
  linked_adjustment public.inventory_transactions%ROWTYPE;
  tx_id_text text;
  restored integer := 0;
BEGIN
  actor_role := CASE WHEN auth.role() = 'service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role IS NULL OR actor_role NOT IN ('Owner','Admin','service_role') THEN
    RAISE EXCEPTION 'Hanya Owner/Admin yang dapat membuka koreksi material' USING ERRCODE = '42501';
  END IF;
  IF length(trim(coalesce(p_reason,''))) < 5 THEN RAISE EXCEPTION 'Alasan koreksi minimal 5 karakter'; END IF;
  SELECT name INTO actor_name FROM public.user_profiles WHERE id = auth.uid();
  actor_name := coalesce(actor_name, nullif(trim(p_actor_name), ''), actor_role);

  SELECT * INTO sess FROM public.teknisi_material_checkout WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sesi material tidak ditemukan'; END IF;
  IF sess.confirm_status <> 'CONFIRMED' THEN RAISE EXCEPTION 'Sesi sudah dibuka/diubah pengguna lain'; END IF;

  FOR tx_id_text IN SELECT value FROM jsonb_array_elements_text(coalesce(sess.deduct_tx_ids, '[]'::jsonb)) LOOP
    SELECT * INTO old_tx FROM public.inventory_transactions WHERE id = tx_id_text::bigint FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Transaksi potongan % tidak ditemukan; koreksi dibatalkan', tx_id_text; END IF;
    INSERT INTO public.inventory_transactions
      (inventory_code, inventory_name, order_id, report_id, unit_id, unit_label,
       qty, qty_actual, type, teknisi_name, customer_name, job_date, notes,
       created_by, created_by_name)
    VALUES
      (old_tx.inventory_code, old_tx.inventory_name, old_tx.order_id, old_tx.report_id,
       old_tx.unit_id, old_tx.unit_label, abs(old_tx.qty), abs(coalesce(old_tx.qty_actual, old_tx.qty)),
       'adjustment', old_tx.teknisi_name, old_tx.customer_name, old_tx.job_date,
       'Buka koreksi Material Harian — stok dikembalikan oleh ' || actor_name || ' (' || trim(p_reason) || ')',
       auth.uid(), actor_name);
    IF old_tx.unit_id IS NOT NULL THEN
      UPDATE public.inventory_units SET stock = stock + abs(old_tx.qty), updated_at = now()
       WHERE id = old_tx.unit_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Unit transaksi % tidak ditemukan', tx_id_text; END IF;
    END IF;

    -- Koreksi timbang adalah bagian dari mutasi yang sama. Balikkan juga koreksinya,
    -- sehingga buka-koreksi selalu kembali tepat ke stok sebelum konfirmasi.
    FOR linked_adjustment IN
      SELECT * FROM public.inventory_transactions
       WHERE source_transaction_id = old_tx.id AND type = 'adjustment'
       FOR UPDATE
    LOOP
      INSERT INTO public.inventory_transactions
        (inventory_code, inventory_name, order_id, report_id, unit_id, unit_label,
         qty, qty_actual, type, teknisi_name, customer_name, job_date, notes,
         created_by, created_by_name, source_transaction_id)
      VALUES
        (linked_adjustment.inventory_code, linked_adjustment.inventory_name,
         linked_adjustment.order_id, linked_adjustment.report_id,
         linked_adjustment.unit_id, linked_adjustment.unit_label,
         -linked_adjustment.qty, -coalesce(linked_adjustment.qty_actual, linked_adjustment.qty),
         'adjustment', linked_adjustment.teknisi_name, linked_adjustment.customer_name,
         linked_adjustment.job_date,
         'Pembalikan koreksi timbang transaksi ' || linked_adjustment.id || ' oleh ' || actor_name,
         auth.uid(), actor_name, linked_adjustment.id);
      IF linked_adjustment.unit_id IS NOT NULL THEN
        UPDATE public.inventory_units
           SET stock = stock - linked_adjustment.qty, updated_at = now()
         WHERE id = linked_adjustment.unit_id AND stock - linked_adjustment.qty >= 0;
        IF NOT FOUND THEN RAISE EXCEPTION 'Stok unit tidak valid saat membalik koreksi transaksi %', linked_adjustment.id; END IF;
      END IF;
    END LOOP;

    IF old_tx.qty_actual IS NOT NULL
       AND abs(abs(old_tx.qty_actual) - abs(old_tx.qty)) >= 0.001
       AND NOT EXISTS (
         SELECT 1 FROM public.inventory_transactions
          WHERE source_transaction_id = old_tx.id AND type = 'adjustment'
       ) THEN
      RAISE EXCEPTION 'Koreksi timbang lama untuk transaksi % belum memiliki tautan audit; buka-koreksi dibatalkan', old_tx.id;
    END IF;
    restored := restored + 1;
  END LOOP;

  UPDATE public.teknisi_material_checkout
     SET confirm_status = 'PENDING', confirmed_by = NULL, confirmed_at = NULL,
         deduct_tx_ids = '[]'::jsonb,
         confirm_notes = 'Dibuka untuk koreksi oleh ' || actor_name || ': ' || trim(p_reason),
         updated_at = now()
   WHERE id = sess.id;
  RETURN jsonb_build_object('session_id', sess.id, 'restored_count', restored);
END $function$

functions.restock_inventory_atomic:
CREATE OR REPLACE FUNCTION public.restock_inventory_atomic(p_code text, p_qty numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_date date DEFAULT CURRENT_DATE, p_notes text DEFAULT NULL::text, p_create_expense boolean DEFAULT false, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE actor_role text; actor_name text; item public.inventory%ROWTYPE; new_hpp numeric; total_cost_value numeric; result public.inventory%ROWTYPE;
BEGIN
  actor_role := CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role IS NULL OR actor_role NOT IN ('Owner','Admin','service_role') THEN RAISE EXCEPTION 'Akses ditolak' USING ERRCODE='42501'; END IF;
  IF coalesce(p_qty,0)<=0 OR coalesce(p_unit_cost,0)<0 THEN RAISE EXCEPTION 'Qty/harga tidak valid'; END IF;
  SELECT * INTO item FROM public.inventory WHERE code=p_code FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Material tidak ditemukan'; END IF;
  IF EXISTS(SELECT 1 FROM public.inventory_units WHERE inventory_code=p_code) THEN
    RAISE EXCEPTION 'Material ini memakai tabung/roll fisik; tambahkan unit baru agar identitas stok tetap jelas';
  END IF;
  SELECT name INTO actor_name FROM public.user_profiles WHERE id=auth.uid(); actor_name:=coalesce(actor_name,nullif(trim(p_actor_name),''),actor_role);
  total_cost_value:=CASE WHEN coalesce(p_unit_cost,0)>0 THEN round(p_qty*p_unit_cost) ELSE NULL END;
  new_hpp:=CASE WHEN coalesce(p_unit_cost,0)>0 AND coalesce(item.stock,0)+p_qty>0
    THEN round(((coalesce(item.stock,0)*coalesce(item.purchase_price,0))+(p_qty*p_unit_cost))/(coalesce(item.stock,0)+p_qty),2)
    ELSE item.purchase_price END;
  INSERT INTO public.inventory_transactions(inventory_code,inventory_name,qty,type,unit_cost,total_cost,notes,created_by,created_by_name)
  VALUES(item.code,item.name,p_qty,'restock',nullif(p_unit_cost,0),total_cost_value,coalesce(nullif(trim(p_notes),''),'Restock manual'),auth.uid(),actor_name);
  IF coalesce(p_unit_cost,0)>0 THEN
    UPDATE public.inventory SET purchase_price=new_hpp,purchase_price_last=p_unit_cost,
      purchase_price_source='restock',purchase_price_updated_at=now(),updated_at=now() WHERE code=item.code;
  END IF;
  IF p_create_expense AND total_cost_value>0 THEN
    INSERT INTO public.expenses(category,subcategory,amount,date,description,item_name,inventory_code,qty,unit,unit_cost,
      stock_linked_at,stock_linked_by,created_by,last_changed_by,source,allocation_status)
    VALUES('material_purchase',CASE WHEN item.material_type='freon' THEN 'Freon' WHEN item.material_type='pipa' THEN 'Pipa AC' WHEN item.material_type='kabel' THEN 'Kabel' ELSE 'Material Lain' END,
      total_cost_value,coalesce(p_date,current_date),coalesce(nullif(trim(p_notes),''),'Restock '||item.name||' '||p_qty||' '||item.unit),
      item.name||' '||p_qty||' '||item.unit,item.code,p_qty,item.unit,p_unit_cost,now(),actor_name,actor_name,actor_name,'restock','STOCK');
  END IF;
  SELECT * INTO result FROM public.inventory WHERE code=item.code;
  RETURN jsonb_build_object('inventory',to_jsonb(result),'expense_created',p_create_expense AND total_cost_value>0);
END $function$

functions.restore_inventory_stock:
CREATE OR REPLACE FUNCTION public.restore_inventory_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  baru numeric;
  ada_unit boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM inventory_units WHERE inventory_code = OLD.inventory_code) INTO ada_unit;
  IF ada_unit THEN RETURN OLD; END IF;
  SELECT stock - OLD.qty INTO baru FROM inventory WHERE code = OLD.inventory_code;
  UPDATE inventory
     SET stock = baru,
         status = CASE WHEN baru <= 0 THEN 'OUT' WHEN baru <= min_alert THEN 'CRITICAL' WHEN baru <= reorder THEN 'WARNING' ELSE 'OK' END,
         updated_at = NOW()
   WHERE code = OLD.inventory_code;
  RETURN OLD;
END;
$function$

functions.save_schedule_plan:
CREATE OR REPLACE FUNCTION public.save_schedule_plan(p_request_id uuid, p_order_id text, p_plan jsonb, p_expected jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  role_name text; actor text; mkey text; request_value jsonb; result_value jsonb; claimed integer;
  old_row public.orders%ROWTYPE; saved public.orders%ROWTYPE; customer_row public.customers%ROWTYPE;
  expected_value jsonb; target_date date; start_time time; end_time time; target_status text; team text;
  crew jsonb; people text[]:=ARRAY[]::text[]; techs text[]:=ARRAY[]::text[]; helpers text[]:=ARRAY[]::text[];
  member text; member_role text; person text; i integer; n integer; phone_value text; notes_value text; contract_id uuid;
BEGIN
  role_name:=public.get_my_role();
  IF role_name IS NULL OR role_name NOT IN ('Owner','Admin') THEN RAISE EXCEPTION 'Hanya Owner/Admin dapat mengubah planning' USING ERRCODE='42501'; END IF;
  IF p_request_id IS NULL OR nullif(trim(p_order_id),'') IS NULL OR length(p_order_id)>100 OR jsonb_typeof(p_plan) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Permintaan planning tidak lengkap'; END IF;
  SELECT name INTO actor FROM public.user_profiles WHERE id=auth.uid(); actor:=coalesce(actor,role_name);
  mkey:='schedule-plan:'||p_request_id::text;
  request_value:=jsonb_build_object('id',p_order_id,'plan',p_plan,'expected',p_expected,'reason',p_reason);
  INSERT INTO public.operational_mutations(mutation_key,operation,actor_id,actor_name)
    VALUES(mkey,'SCHEDULE_PLAN',auth.uid(),actor) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS claimed=ROW_COUNT;
  IF claimed=0 THEN
    SELECT result INTO result_value FROM public.operational_mutations WHERE mutation_key=mkey;
    IF result_value->'request' IS DISTINCT FROM request_value THEN RAISE EXCEPTION 'ID permintaan telah digunakan untuk data berbeda'; END IF;
    RETURN result_value||jsonb_build_object('replayed',true);
  END IF;
  -- Serialize saves through this endpoint, including team-only reservations without people.
  PERFORM pg_advisory_xact_lock(hashtext('aclean:schedule-plan'));
  SELECT * INTO old_row FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF p_expected IS NULL AND old_row.id IS NOT NULL THEN RAISE EXCEPTION 'Job sudah ada; muat ulang sebelum mengubah'; END IF;
  IF p_expected IS NOT NULL THEN
    IF old_row.id IS NULL THEN RAISE EXCEPTION 'Job tidak ditemukan'; END IF;
    IF old_row.status NOT IN ('PENDING','CONFIRMED','DISPATCHED') OR old_row.project_id IS NOT NULL THEN RAISE EXCEPTION 'Job berjalan/ditutup atau project harus diubah melalui alur operasional terkait'; END IF;
    SELECT jsonb_object_agg(k,to_jsonb(old_row)->k) INTO expected_value FROM unnest(ARRAY['date','time','time_end','team_slot','status','notes','teknisi','teknisi2','teknisi3','helper','helper2','helper3']) k;
    IF expected_value IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Planning berubah oleh admin lain. Tutup dan buka ulang job.' USING ERRCODE='40001'; END IF;
    IF p_plan->>'service' IS DISTINCT FROM old_row.service THEN RAISE EXCEPTION 'Jenis servis job tidak dapat diubah'; END IF;
    IF length(trim(coalesce(p_reason,'')))<5 THEN RAISE EXCEPTION 'Alasan perubahan wajib diisi'; END IF;
  END IF;
  IF coalesce(p_plan->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Tanggal wajib diisi'; END IF;
  target_date:=(p_plan->>'date')::date;
  IF old_row.id IS NULL AND target_date<(now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Planning baru harus hari ini atau mendatang'; END IF;
  IF coalesce(p_plan->>'time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' OR coalesce(p_plan->>'time_end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'Jam tidak valid'; END IF;
  start_time:=(p_plan->>'time')::time; end_time:=(p_plan->>'time_end')::time;
  IF start_time<'09:00' OR start_time=end_time OR (start_time<'18:00' AND (end_time<start_time OR end_time>'18:00'))
    OR (start_time>='18:00' AND end_time<start_time AND end_time>'06:00')
    OR upper(public.slot_tsrange(target_date,start_time::text,end_time::text))-lower(public.slot_tsrange(target_date,start_time::text,end_time::text))>interval '12 hours'
  THEN RAISE EXCEPTION 'Jam pekerjaan tidak valid; malam berakhir paling lambat 06:00 esok hari'; END IF;
  target_status:=p_plan->>'status'; team:=nullif(trim(p_plan->>'team_slot'),'');
  IF target_status IS NULL OR target_status NOT IN ('PENDING','CONFIRMED','CANCELLED') OR (target_status='CANCELLED' AND old_row.id IS NULL) THEN RAISE EXCEPTION 'Status planning tidak valid'; END IF;
  IF coalesce(p_plan->>'units','') !~ '^\d+$' OR (p_plan->>'units')::integer NOT BETWEEN 1 AND 100 OR nullif(trim(p_plan->>'service'),'') IS NULL THEN RAISE EXCEPTION 'Layanan/jumlah unit tidak valid'; END IF;
  IF team IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.team_presets p WHERE p.slot=team) AND NOT EXISTS(SELECT 1 FROM public.daily_team_slots d WHERE d.date=target_date AND d.slot=team) AND team IS DISTINCT FROM old_row.team_slot THEN RAISE EXCEPTION 'Team tidak ada pada preset/roster'; END IF;
    IF (start_time>='18:00') IS DISTINCT FROM (team LIKE 'Malam %') THEN RAISE EXCEPTION 'Gunakan slot Malam untuk mulai 18:00 ke atas'; END IF;
    SELECT to_jsonb(d) INTO crew FROM public.daily_team_slots d WHERE d.date=target_date AND d.slot=team FOR SHARE;
    FOR i IN 1..8 LOOP
      member:=nullif(trim(crew->>('member'||i)), '');
      member_role:=coalesce(crew->>('member'||i||'_role'),CASE WHEN i=1 THEN 'teknisi' ELSE 'helper' END);
      IF member IS NOT NULL AND NOT member=ANY(people) THEN
        people:=array_append(people,member);
        IF member_role='teknisi' THEN techs:=array_append(techs,member); ELSE helpers:=array_append(helpers,member); END IF;
      END IF;
    END LOOP;
    IF coalesce(array_length(techs,1),0)=0 AND coalesce(array_length(helpers,1),0)>0 THEN techs:=ARRAY[helpers[1]];helpers:=helpers[2:]; END IF;
  END IF;
  -- Coordinate named personnel with the existing slot-claim path as well.
  FOR person IN SELECT DISTINCT unnest(people) ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext(person||'|'||target_date::text));
  END LOOP;
  IF target_status<>'CANCELLED' AND team IS NOT NULL THEN
    SELECT count(*) INTO n FROM public.orders o WHERE o.id<>p_order_id AND o.date=target_date AND o.team_slot=team AND o.status IN ('PENDING','CONFIRMED','DISPATCHED','ON_SITE','IN_PROGRESS');
    IF n>=6 THEN RAISE EXCEPTION 'Team sudah memiliki 6 pekerjaan pada tanggal ini'; END IF;
    IF EXISTS(
      SELECT 1 FROM public.orders o LEFT JOIN public.daily_team_slots r ON r.date=o.date AND r.slot=o.team_slot
      WHERE o.id<>p_order_id AND o.date BETWEEN target_date-1 AND target_date+1 AND o.status IN ('PENDING','CONFIRMED','DISPATCHED','ON_SITE','IN_PROGRESS','WORKING')
      AND (o.team_slot=team OR people && ARRAY[o.teknisi,o.teknisi2,o.teknisi3,o.helper,o.helper2,o.helper3,r.member1,r.member2,r.member3,r.member4,r.member5,r.member6,r.member7,r.member8])
      AND (o.time IS NULL OR o.time_end IS NULL OR public.slot_tsrange(target_date,start_time::text,end_time::text) && public.slot_tsrange(o.date,o.time::text,o.time_end::text))
    ) THEN RAISE EXCEPTION 'Slot tim atau anggota bertabrakan dengan pekerjaan lain'; END IF;
  END IF;
  notes_value:=coalesce(p_plan->>'notes','');
  IF length(notes_value)>10000 OR length(coalesce(p_reason,''))>2000 THEN RAISE EXCEPTION 'Catatan terlalu panjang'; END IF;
  IF old_row.id IS NULL THEN
    phone_value:=regexp_replace(coalesce(p_plan->>'phone',''),'[^0-9]','','g');
    IF phone_value LIKE '0%' THEN phone_value:='62'||substr(phone_value,2); END IF;
    IF phone_value !~ '^\d{8,15}$' OR length(trim(coalesce(p_plan->>'customer',''))) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'Nama/nomor pelanggan tidak valid'; END IF;
    IF nullif(p_plan->>'customer_id','') IS NOT NULL THEN
      SELECT * INTO customer_row FROM public.customers WHERE id=p_plan->>'customer_id' FOR UPDATE;
      IF customer_row.id IS NULL OR regexp_replace(customer_row.phone,'^0','62') IS DISTINCT FROM phone_value THEN RAISE EXCEPTION 'Lokasi pelanggan tidak sesuai nomor'; END IF;
    ELSE
      SELECT * INTO customer_row FROM public.customers WHERE phone=phone_value AND lower(trim(name))=lower(trim(p_plan->>'customer')) LIMIT 1 FOR UPDATE;
    END IF;
    IF customer_row.id IS NULL THEN
      INSERT INTO public.customers(name,phone,address,area,notes,is_vip,total_orders,joined_date)
      VALUES(trim(p_plan->>'customer'),phone_value,coalesce(p_plan->>'address',''),coalesce(p_plan->>'area',''),'',false,0,target_date) RETURNING * INTO customer_row;
    END IF;
    SELECT id INTO contract_id FROM public.maintenance_clients WHERE customer_id=customer_row.id LIMIT 1;
    INSERT INTO public.orders(id,customer,customer_id,phone,address,area,service,type,units,date,time,time_end,team_slot,status,notes,source,dispatch,last_changed_by,maintenance_client_id)
    VALUES(p_order_id,customer_row.name,customer_row.id,phone_value,p_plan->>'address',p_plan->>'area',p_plan->>'service',p_plan->>'type',(p_plan->>'units')::integer,target_date,start_time,end_time,team,target_status,notes_value,CASE WHEN p_plan->>'source'='whatsapp' THEN 'whatsapp' ELSE 'manual' END,false,actor,contract_id);
    -- Existing sync_customer_order_stats trigger owns completed-service counters.
  ELSE
    notes_value:=notes_value||E'\n[Planning '||to_char(now() AT TIME ZONE 'Asia/Jakarta','YYYY-MM-DD HH24:MI')||' WIB · '||actor||'] '||trim(p_reason);
    UPDATE public.orders SET date=target_date,time=start_time,time_end=end_time,team_slot=team,status=target_status,
      units=(p_plan->>'units')::integer,notes=notes_value,dispatch=false,dispatch_at=NULL,last_changed_by=actor WHERE id=p_order_id;
  END IF;
  -- Clear old-day personnel and reservations in the same transaction as rescheduling.
  UPDATE public.orders SET teknisi=techs[1],teknisi2=techs[2],teknisi3=techs[3],helper=helpers[1],helper2=helpers[2],helper3=helpers[3] WHERE id=p_order_id RETURNING * INTO saved;
  DELETE FROM public.technician_schedule WHERE order_id=p_order_id AND status='ACTIVE';
  IF target_status<>'CANCELLED' THEN
    FOREACH person IN ARRAY people LOOP
      IF public.try_claim_teknisi_slot(person,target_date,p_order_id,p_plan->>'time',p_plan->>'time_end') IS DISTINCT FROM true THEN RAISE EXCEPTION 'Anggota tim tidak tersedia pada jam tersebut'; END IF;
    END LOOP;
  END IF;
  result_value:=jsonb_build_object('order',to_jsonb(saved),'before',CASE WHEN old_row.id IS NULL THEN NULL ELSE to_jsonb(old_row) END,'request',request_value,'reason',p_reason,'replayed',false);
  UPDATE public.operational_mutations SET result=result_value,completed_at=now() WHERE mutation_key=mkey;
  RETURN result_value;
END $function$

functions.settle_invoice_atomic:
CREATE OR REPLACE FUNCTION public.settle_invoice_atomic(p_invoice_id text, p_payment_id uuid, p_paid_at date, p_method text DEFAULT 'transfer'::text, p_notes text DEFAULT NULL::text, p_payment_proof_url text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_mutation_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  role_name text; actor text; inv public.invoices%ROWTYPE; payment public.invoice_payments%ROWTYPE;
  remaining numeric; result_value jsonb; claimed integer; mkey text;
BEGIN
  role_name := CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF role_name NOT IN ('Owner','Admin','Finance','service_role') THEN RAISE EXCEPTION 'Akses pelunasan ditolak' USING ERRCODE='42501'; END IF;
  IF nullif(trim(p_invoice_id),'') IS NULL OR p_payment_id IS NULL OR p_paid_at IS NULL OR nullif(trim(p_method),'') IS NULL THEN
    RAISE EXCEPTION 'Data pelunasan tidak lengkap';
  END IF;
  SELECT name INTO actor FROM public.user_profiles WHERE id=auth.uid();
  actor:=coalesce(actor,nullif(trim(p_actor_name),''),role_name);
  mkey:=coalesce(nullif(trim(p_mutation_key),''),'settle:'||p_payment_id::text);
  INSERT INTO public.operational_mutations(mutation_key,operation,actor_id,actor_name)
  VALUES(mkey,'SETTLE_INVOICE',auth.uid(),actor) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS claimed=ROW_COUNT;
  IF claimed=0 THEN
    SELECT om.result INTO result_value FROM public.operational_mutations om WHERE om.mutation_key=mkey;
    RETURN result_value||jsonb_build_object('replayed',true);
  END IF;

  SELECT * INTO inv FROM public.invoices WHERE id=p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice tidak ditemukan'; END IF;
  SELECT * INTO payment FROM public.invoice_payments WHERE id=p_payment_id;
  IF FOUND THEN RAISE EXCEPTION 'ID pembayaran telah digunakan'; END IF;
  IF inv.status NOT IN ('UNPAID','OVERDUE','PARTIAL_PAID','PENDING_APPROVAL') THEN
    RAISE EXCEPTION 'Invoice sudah % — tidak dapat dilunasi ulang',inv.status;
  END IF;
  remaining:=greatest(0,coalesce(inv.total,0)-coalesce(inv.paid_amount,0));
  IF remaining<=0 THEN RAISE EXCEPTION 'Sisa tagihan invoice sudah nol'; END IF;

  INSERT INTO public.invoice_payments(id,invoice_id,amount,method,notes,paid_at,recorded_by,recorded_by_name)
  VALUES(p_payment_id,inv.id,remaining,lower(trim(p_method)),nullif(trim(p_notes),''),p_paid_at,auth.uid()::text,actor)
  RETURNING * INTO payment;

  UPDATE public.invoices SET status='PAID',paid_at=p_paid_at,paid_method=lower(trim(p_method)),
    paid_amount=coalesce(total,0),remaining_amount=0,
    payment_proof_url=coalesce(nullif(trim(p_payment_proof_url),''),payment_proof_url),
    pdf_url=NULL,pdf_generated_at=NULL,last_changed_by=actor
  WHERE id=inv.id RETURNING * INTO inv;
  UPDATE public.orders SET status='PAID',last_changed_by=actor
    WHERE id=inv.job_id OR invoice_id=inv.id;
  IF nullif(trim(inv.phone),'') IS NOT NULL THEN
    UPDATE public.customers SET last_service=p_paid_at WHERE phone=inv.phone;
  END IF;

  result_value:=jsonb_build_object('invoice',to_jsonb(inv),'payment',to_jsonb(payment),'replayed',false);
  UPDATE public.operational_mutations SET result=result_value,completed_at=now() WHERE mutation_key=mkey;
  RETURN result_value;
END $function$

functions.try_claim_teknisi_slot:
CREATE OR REPLACE FUNCTION public.try_claim_teknisi_slot(p_teknisi text, p_date date, p_order_id text, p_start text, p_end text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_cnt integer;
  c_active constant text[] := ARRAY['PENDING','CONFIRMED','DISPATCHED','IN_PROGRESS','ON_SITE','WORKING'];
BEGIN
  IF p_teknisi IS NULL OR btrim(p_teknisi) = '' OR p_date IS NULL THEN RETURN true; END IF;
  IF nullif(trim(p_start),'') IS NULL OR nullif(trim(p_end),'') IS NULL OR p_start::time = p_end::time THEN
    RAISE EXCEPTION 'Jam mulai/selesai tidak valid';
  END IF;

  IF upper(public.slot_tsrange(p_date,p_start,p_end))-lower(public.slot_tsrange(p_date,p_start,p_end))>interval '12 hours' THEN RAISE EXCEPTION 'Durasi maksimal 12 jam'; END IF;
  -- Lock per person (not per date), because an overnight claim spans two dates.
  PERFORM pg_advisory_xact_lock(hashtext('schedule:' || p_teknisi));

  DELETE FROM public.technician_schedule ts
   WHERE ts.teknisi=p_teknisi AND ts.date BETWEEN p_date-1 AND p_date+1
     AND NOT EXISTS (
       SELECT 1 FROM public.orders o
        WHERE o.id=ts.order_id AND o.status=ANY(c_active)
     );

  SELECT count(*) INTO v_cnt
    FROM public.technician_schedule ts
    JOIN public.orders o ON o.id=ts.order_id
   WHERE ts.teknisi=p_teknisi AND ts.date=p_date AND ts.status='ACTIVE'
     AND ts.order_id<>p_order_id AND o.status=ANY(c_active);
  IF v_cnt>=6 THEN RETURN false; END IF;

  SELECT count(*) INTO v_cnt
    FROM public.technician_schedule ts
    JOIN public.orders o ON o.id=ts.order_id
   WHERE ts.teknisi=p_teknisi AND ts.date BETWEEN p_date-1 AND p_date+1 AND ts.status='ACTIVE'
     AND ts.order_id<>p_order_id AND o.status=ANY(c_active)
     AND public.slot_tsrange(p_date,p_start,p_end) && public.slot_tsrange(ts.date,ts.time_start,ts.time_end);
  IF v_cnt>0 THEN RETURN false; END IF;

  INSERT INTO public.technician_schedule(order_id,teknisi,date,time_start,time_end,status)
  VALUES(p_order_id,p_teknisi,p_date,p_start,p_end,'ACTIVE');
  RETURN true;
END $function$

functions.update_inventory_stock:
CREATE OR REPLACE FUNCTION public.update_inventory_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  baru numeric;
  ada_unit boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM inventory_units WHERE inventory_code = NEW.inventory_code) INTO ada_unit;
  IF ada_unit THEN RETURN NEW; END IF;
  SELECT stock + NEW.qty INTO baru FROM inventory WHERE code = NEW.inventory_code;
  UPDATE inventory
     SET stock = baru,
         status = CASE WHEN baru <= 0 THEN 'OUT' WHEN baru <= min_alert THEN 'CRITICAL' WHEN baru <= reorder THEN 'WARNING' ELSE 'OK' END,
         updated_at = NOW()
   WHERE code = NEW.inventory_code;
  RETURN NEW;
END;
$function$

functions.update_order_workflow_atomic:
CREATE OR REPLACE FUNCTION public.update_order_workflow_atomic(p_order_id text, p_patch jsonb, p_actor_name text DEFAULT NULL::text, p_mutation_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  role_name text;
  actor text;
  ord public.orders%ROWTYPE;
  result_value jsonb;
  claimed integer;
  mkey text;
  slot_ok boolean;
  active_statuses constant text[] := ARRAY['PENDING','CONFIRMED','DISPATCHED','IN_PROGRESS','ON_SITE','WORKING'];
BEGIN
  role_name := CASE WHEN auth.role() = 'service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF role_name NOT IN ('Owner','Admin','service_role') THEN
    RAISE EXCEPTION 'Akses edit order ditolak' USING ERRCODE = '42501';
  END IF;
  IF nullif(trim(p_order_id), '') IS NULL OR jsonb_typeof(p_patch) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Payload edit order tidak lengkap';
  END IF;

  SELECT name INTO actor FROM public.user_profiles WHERE id = auth.uid();
  actor := coalesce(actor, nullif(trim(p_actor_name), ''), role_name);
  mkey := coalesce(nullif(trim(p_mutation_key), ''),
    'order-update:' || p_order_id || ':' || md5(p_patch::text));

  INSERT INTO public.operational_mutations(mutation_key, operation, actor_id, actor_name)
  VALUES (mkey, 'UPDATE_ORDER', auth.uid(), actor)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS claimed = ROW_COUNT;
  IF claimed = 0 THEN
    SELECT result INTO result_value FROM public.operational_mutations WHERE mutation_key = mkey;
    RETURN coalesce(result_value, '{}'::jsonb) || jsonb_build_object('replayed', true);
  END IF;

  SELECT * INTO ord FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF;

  UPDATE public.orders o SET
    customer  = CASE WHEN p_patch ? 'customer'  THEN p_patch->>'customer'  ELSE o.customer END,
    phone     = CASE WHEN p_patch ? 'phone'     THEN p_patch->>'phone'     ELSE o.phone END,
    address   = CASE WHEN p_patch ? 'address'   THEN p_patch->>'address'   ELSE o.address END,
    area      = CASE WHEN p_patch ? 'area'      THEN p_patch->>'area'      ELSE o.area END,
    service   = CASE WHEN p_patch ? 'service'   THEN p_patch->>'service'   ELSE o.service END,
    type      = CASE WHEN p_patch ? 'type'      THEN p_patch->>'type'      ELSE o.type END,
    units     = CASE WHEN p_patch ? 'units'     THEN greatest(coalesce((p_patch->>'units')::integer, 1), 1) ELSE o.units END,
    teknisi   = CASE WHEN p_patch ? 'teknisi'   THEN nullif(trim(p_patch->>'teknisi'), '') ELSE o.teknisi END,
    helper    = CASE WHEN p_patch ? 'helper'    THEN nullif(trim(p_patch->>'helper'), '') ELSE o.helper END,
    teknisi2  = CASE WHEN p_patch ? 'teknisi2'  THEN nullif(trim(p_patch->>'teknisi2'), '') ELSE o.teknisi2 END,
    helper2   = CASE WHEN p_patch ? 'helper2'   THEN nullif(trim(p_patch->>'helper2'), '') ELSE o.helper2 END,
    teknisi3  = CASE WHEN p_patch ? 'teknisi3'  THEN nullif(trim(p_patch->>'teknisi3'), '') ELSE o.teknisi3 END,
    helper3   = CASE WHEN p_patch ? 'helper3'   THEN nullif(trim(p_patch->>'helper3'), '') ELSE o.helper3 END,
    date      = CASE WHEN p_patch ? 'date'      THEN (p_patch->>'date')::date ELSE o.date END,
    time      = CASE WHEN p_patch ? 'time'      THEN (p_patch->>'time')::time ELSE o.time END,
    time_end  = CASE WHEN p_patch ? 'time_end'  THEN (p_patch->>'time_end')::time ELSE o.time_end END,
    status    = CASE WHEN p_patch ? 'status'    THEN p_patch->>'status' ELSE o.status END,
    notes     = CASE WHEN p_patch ? 'notes'     THEN coalesce(p_patch->>'notes', '') ELSE o.notes END,
    last_changed_by = actor
  WHERE o.id = p_order_id
  RETURNING * INTO ord;

  -- Hapus klaim lama dan buat klaim baru di transaksi yang sama. Jika klaim gagal,
  -- RAISE akan me-rollback order sekaligus mengembalikan klaim lama.
  DELETE FROM public.technician_schedule WHERE order_id = ord.id;
  IF nullif(trim(ord.teknisi), '') IS NOT NULL
     AND ord.date IS NOT NULL
     AND ord.time IS NOT NULL
     AND ord.time_end IS NOT NULL
     AND ord.status = ANY(active_statuses) THEN
    SELECT public.try_claim_teknisi_slot(ord.teknisi, ord.date, ord.id, ord.time::text, ord.time_end::text) INTO slot_ok;
    IF slot_ok IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'Slot teknisi baru saja terisi';
    END IF;
  END IF;

  result_value := jsonb_build_object('order', to_jsonb(ord), 'replayed', false);
  UPDATE public.operational_mutations SET result = result_value, completed_at = now()
  WHERE mutation_key = mkey;
  RETURN result_value;
END $function$

functions.adjust_inventory_item_atomic:
CREATE OR REPLACE FUNCTION public.adjust_inventory_item_atomic(p_code text, p_target_stock numeric, p_price numeric, p_reorder numeric, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE actor_role text; actor_name text; item public.inventory%ROWTYPE; delta numeric; result public.inventory%ROWTYPE;
BEGIN
  actor_role := CASE WHEN auth.role()='service_role' THEN 'service_role' ELSE public.get_my_role() END;
  IF actor_role IS NULL OR actor_role NOT IN ('Owner','Admin','service_role') THEN RAISE EXCEPTION 'Akses ditolak' USING ERRCODE='42501'; END IF;
  SELECT * INTO item FROM public.inventory WHERE code=p_code FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Material tidak ditemukan'; END IF;
  IF EXISTS(SELECT 1 FROM public.inventory_units WHERE inventory_code=p_code) AND p_target_stock IS DISTINCT FROM item.stock THEN
    RAISE EXCEPTION 'Stok material ber-unit harus diubah dari tabung/roll fisiknya';
  END IF;
  IF coalesce(p_target_stock,0)<0 OR coalesce(p_price,0)<0 THEN RAISE EXCEPTION 'Stok/harga tidak boleh negatif'; END IF;
  SELECT name INTO actor_name FROM public.user_profiles WHERE id=auth.uid(); actor_name:=coalesce(actor_name,nullif(trim(p_actor_name),''),actor_role);
  delta:=p_target_stock-item.stock;
  UPDATE public.inventory SET price=p_price,reorder=p_reorder,updated_at=now() WHERE code=p_code;
  IF delta<>0 THEN
    INSERT INTO public.inventory_transactions(inventory_code,inventory_name,qty,type,notes,created_by,created_by_name)
    VALUES(item.code,item.name,delta,CASE WHEN delta>0 THEN 'restock' ELSE 'correction' END,'Koreksi stok manual',auth.uid(),actor_name);
  END IF;
  SELECT * INTO result FROM public.inventory WHERE code=p_code; RETURN to_jsonb(result);
END $function$

functions.link_expense_to_stock:
CREATE OR REPLACE FUNCTION public.link_expense_to_stock(p_expense_id uuid, p_inventory_code text, p_qty numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  actor_role text := public.get_my_role();
  actor_name text;
  e public.expenses%ROWTYPE;
  i public.inventory%ROWTYPE;
  unit_cost_value numeric;
  new_hpp numeric;
BEGIN
  IF actor_role NOT IN ('Owner','Admin') THEN
    RAISE EXCEPTION 'Hanya Owner/Admin boleh menautkan nota ke stok' USING ERRCODE = '42501';
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN RAISE EXCEPTION 'Jumlah harus lebih dari 0'; END IF;

  SELECT name INTO actor_name FROM public.user_profiles WHERE id = auth.uid();
  SELECT * INTO e FROM public.expenses WHERE id = p_expense_id FOR UPDATE;
  IF NOT FOUND OR e.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Nota tidak ditemukan'; END IF;
  IF e.category <> 'material_purchase' THEN RAISE EXCEPTION 'Nota bukan pembelian material'; END IF;
  IF e.stock_linked_at IS NOT NULL THEN RAISE EXCEPTION 'Nota sudah pernah ditautkan'; END IF;
  IF e.approval_status = 'PENDING_APPROVAL' OR e.validation_status = 'PENDING_AI' THEN
    RAISE EXCEPTION 'Nota harus disetujui sebelum menjadi stok';
  END IF;

  SELECT * INTO i FROM public.inventory WHERE code = p_inventory_code FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Item inventori tidak ditemukan'; END IF;

  unit_cost_value := round((e.amount / p_qty)::numeric, 2);
  new_hpp := CASE WHEN coalesce(i.stock,0) + p_qty > 0
    THEN round(((coalesce(i.stock,0) * coalesce(i.purchase_price,0)) + (p_qty * unit_cost_value)) / (coalesce(i.stock,0) + p_qty), 2)
    ELSE unit_cost_value END;

  UPDATE public.expenses SET
    inventory_code = i.code, qty = p_qty, unit = i.unit, unit_cost = unit_cost_value,
    stock_linked_at = now(), stock_linked_by = coalesce(actor_name, actor_role),
    allocation_status = 'STOCK', last_changed_by = coalesce(actor_name, actor_role)
  WHERE id = e.id;

  UPDATE public.inventory SET
    purchase_price = new_hpp, purchase_price_last = unit_cost_value,
    purchase_price_source = 'nota', purchase_price_updated_at = now(), updated_at = now()
  WHERE code = i.code;

  INSERT INTO public.inventory_transactions
    (inventory_code, inventory_name, qty, type, unit_cost, total_cost, expense_id, notes, created_by, created_by_name)
  VALUES
    (i.code, i.name, p_qty, 'restock', unit_cost_value, e.amount, e.id,
     'Tautan nota: ' || coalesce(e.item_name, e.subcategory, 'pembelian') || ' (' || e.date || ')',
     auth.uid(), coalesce(actor_name, actor_role));

  RETURN jsonb_build_object(
    'expense', jsonb_build_object('inventory_code',i.code,'qty',p_qty,'unit',i.unit,'unit_cost',unit_cost_value,'stock_linked_at',now(),'stock_linked_by',coalesce(actor_name,actor_role),'allocation_status','STOCK'),
    'inventory', jsonb_build_object('code',i.code,'stock',coalesce(i.stock,0)+p_qty,'purchase_price',new_hpp,'purchase_price_last',unit_cost_value,'purchase_price_source','nota','purchase_price_updated_at',now())
  );
END $function$

functions.guard_inventory_price_columns:
CREATE OR REPLACE FUNCTION public.guard_inventory_price_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  peran text;
BEGIN
  IF (SELECT auth.role()) = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF NEW.price                 IS DISTINCT FROM OLD.price
     OR NEW.purchase_price      IS DISTINCT FROM OLD.purchase_price
     OR NEW.purchase_price_last IS DISTINCT FROM OLD.purchase_price_last
     OR NEW.pack_size           IS DISTINCT FROM OLD.pack_size
     OR NEW.pack_unit           IS DISTINCT FROM OLD.pack_unit
  THEN
    peran := get_my_role();
    IF peran IS NULL OR peran NOT IN ('Owner', 'Admin') THEN
      RAISE EXCEPTION 'Hanya Owner/Admin yang boleh mengubah harga material (role: %)', COALESCE(peran, 'tidak dikenal')
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END $function$

functions.update_inventory_status:
CREATE OR REPLACE FUNCTION public.update_inventory_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF    NEW.stock <= 0             THEN NEW.status := 'OUT';
  ELSIF NEW.stock <= NEW.min_alert THEN NEW.status := 'CRITICAL';
  ELSIF NEW.stock <= NEW.reorder   THEN NEW.status := 'WARNING';
  ELSE                                  NEW.status := 'OK';
  END IF;
  RETURN NEW;
END;
$function$
